/**
 * Hybrid client-side database layer.
 * Tries API routes first (server mode), falls back to localStorage (GitHub Pages).
 */

import { IMPORT_STATS } from './import-data';
import type { ImportLead, ImportEmail } from './import-data';

const statusLabels: Record<string, string> = {
  new: 'New',
  contacted: 'Contacted',
  qualified: 'Qualified',
  proposal: 'Proposal Sent',
  closed: 'Closed'
};

// ===== TYPES =====
export interface Lead {
  id: string;
  name: string;
  company: string;
  email: string;
  phone: string;
  website: string;
  city: string;
  state: string;
  industry: string;
  source: string;
  status: string;
  score: number;
  rating?: number | null;
  user_ratings_total?: number | null;
  address?: string | null;
  category?: string | null;
  website_status?: string | null;
  created_at: string;
  updated_at: string;
}

export interface OutreachEmail {
  id: string;
  lead_id: string;
  lead_name: string;
  subject: string;
  body: string;
  html_body?: string;
  status: string;
  sent_at: string | null;
  opened_at: string | null;
  created_at: string;
}

export interface Deal {
  id: string;
  lead_id: string;
  title: string;
  value: number;
  progress: number;
  status: string;
  kickoff_date: string;
  target_date: string;
  created_at: string;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: string;
  priority: string;
  owner_type: string;
  owner_id: string;
  lead_id: string;
  deadline: string;
  created_at: string;
}

export interface Activity {
  id: string;
  entity_type: string;
  entity_id: string;
  action: string;
  details: string;
  user_id: string;
  created_at: string;
}

export interface Setting {
  id: string;
  key: string;
  value: string;
  updated_at: string;
}

export interface LeadWithStats extends Lead {
  email_count: number;
  last_email_at: string | null;
}

// ===== DOSSIER (OSINT) =====
export interface Dossier {
  id: string;
  lead_id: string;
  // Business info
  business_name: string;
  industry: string;
  location: string;
  website: string;
  phone: string;
  // Contacts
  owner_name: string;
  owner_title: string;
  contact_email: string;
  // Tech & ops
  technology_stack: string[];
  pain_points: string[];
  opportunities: string[];
  // Score & research
  confidence_score: number;
  research_sources: { label: string; url: string }[];
  notes: string;
  // Meta
  created_at: string;
  updated_at: string;
}

// ===== MODE DETECTION =====
let _mode: 'api' | 'local' | null = null;

async function detectMode(): Promise<'api' | 'local'> {
  if (_mode) return _mode;
  
  try {
    // Try to reach the API
    const res = await fetch('/api/leads', { 
      method: 'GET',
      signal: AbortSignal.timeout(3000) // 3 second timeout
    });
    if (res.ok) {
      _mode = 'api';
      console.log('[DB] Using API mode');
      return _mode;
    }
  } catch {
    // API not available
  }
  
  _mode = 'local';
  console.log('[DB] Using localStorage fallback mode');
  return _mode;
}

// ===== LOCAL STORAGE HELPERS =====
function getStorageKey(table: string): string {
  return `lnm_${table}`;
}

function loadFromStorage<T>(table: string): T[] {
  if (typeof window === 'undefined') return [];
  const data = localStorage.getItem(getStorageKey(table));
  return data ? JSON.parse(data) : [];
}

function saveToStorage<T>(table: string, data: T[]): void {
  if (typeof window === 'undefined') return;
  localStorage.setItem(getStorageKey(table), JSON.stringify(data));
}

function generateId(): string {
  return crypto.randomUUID ? crypto.randomUUID() : 
    'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
      const r = Math.random() * 16 | 0;
      const v = c === 'x' ? r : (r & 0x3 | 0x8);
      return v.toString(16);
    });
}

